const photoIndex = {
  base,
  photos};

function findPhotos(query, count = 4) {
  const q = query.toLowerCase();
  const base = photoIndex.base;
  const scored = photoIndex.photos.map((photo) => {
    const score = photo.tags.filter(
      (tag) => q.includes(tag) || tag.split(" ").some((w) => q.includes(w))
    ).length;
    return { photo, score };
  });
  const filtered = scored.filter((s) => s.score > 0);
  filtered.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    return Math.random() - 0.5;
  });
  const results = filtered.slice(0, count).map((s) => ({
    url: base + s.photo.file,
    caption: s.photo.caption
  }));
  if (!results.length) {
    const fallback = [
      { url: base + "camp-smile.avif", caption: "Атмосфера лагеря" },
      { url: base + "camp-group-beanbags.avif", caption: "Дети в лагере" },
      { url: base + "study-dome-group.avif", caption: "Занятия" },
      { url: base + "hackathon-present.avif", caption: "Хакатон" }
    ];
    fallback.sort(() => Math.random() - 0.5);
    return fallback.slice(0, count);
  }
  return results;
}

